import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int substituir = 0;
        int consertar = 0;

        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            if (x < 50) {
                substituir++;
            } else if (x < 85) {
                consertar++;
            }
        }

        System.out.println(substituir + " " + consertar);
    }
}
